.roam-block-container[data-page-links*=".rm-focus"],
.roam-block-container[data-page-links*=".rm-focus"] *,
.roam-block-container[data-page-links*=".rm-focus"] .roam-block,
.roam-block-container[data-page-links*=".rm-focus"] .rm-block-main,
.roam-block-container[data-page-links*=".rm-focus"] .rm-block-children,
.roam-block-container[data-page-links*=".rm-focus"] .rm-block-text,
