.rm-zoom[data-page-links*=".rm-focus"] .roam-block,
.rm-zoom .roam-block-container[data-page-links*=".rm-focus"],
.rm-zoom .roam-block-container[data-page-links*=".rm-focus"] * {
    border-left: none !important;
    border-right: none !important;
    box-shadow: none !important;
    outline: none !important;
    margin-left: 0 !important;
    padding-left: 0 !important;
}

/* Remove any pseudo-element borders */
.roam-block-container[data-page-links*=".rm-focus"]:before,
.roam-block-container[data-page-links*=".rm-focus"]:after,
.roam-block-container[data-page-links*=".rm-focus"] *:before,
.roam-block-container[data-page-links*=".rm-focus"] *:after {
    border-left: none !important;
    box-shadow: none !important;
    outline: none !important;
}

/* Enhanced typography for writing focus */
.roam-block-container[data-page-links*=".rm-focus"] .rm-block-text {
    font-size: 18px !important;
    line-height: 1.7 !important;
    font-family: "Georgia", "Times New Roman", serif !important;
    color: #2d3748 !important;
    max-width: none !important;
}

/* Clean up block spacing */
.roam-block-container[data-page-links*=".rm-focus"] .roam-block {
    margin-bottom: 12px !important;
    margin-top: 0 !important;
}

/* Hide block references and UI chrome */
.roam-block-container[data-page-links*=".rm-focus"] .rm-block-ref {
    background: transparent !important;
    border: none !important;
}

.roam-block-container[data-page-links*=".rm-focus"] .block-highlight-blue {
    background: transparent !important;
    border: none !important;
